(4195264, 601943, 84656, '<td valign="top">Good DOF, and colours and contrast handled nicely.</td>', 'Good DOF, and colours and contrast handled nicely.', '2007-10-25 15:02:10.000000', NULL, 1),
(4195265, 601943, 81382, '<td valign="top">Great colour and sharpness. Perhaps a slight cw rotation during the cropping stage just to level the would be horizon would have been spot on</td>', 'Great colour and sharpness. Perhaps a slight cw rotation during the cropping stage just to level the would be horizon would have been spot on', '2007-10-25 15:02:31.000000', NULL, 1),
(4195270, 604125, 81382, '<td valign="top">A bit too pastally. Red colour cast is a shame, getting the white balance sorted would have made a difference. Sharpening it up would also help</td>', 'A bit too pastally. Red colour cast is a shame, getting the white balance sorted would have made a difference. Sharpening it up would also help', '2007-10-25 15:04:18.000000', NULL, 1),
(4195273, 601743, 81382, '<td valign="top">Cropped out just slightly and placed more towards the right would have improved composition. The sky looks a little GIF like with respect to colour bit-depth</td>', 'Cropped out just slightly and placed more towards the right would have improved composition. The sky looks a little GIF like with respect to colour bit-depth', '2007-10-25 15:05:50.000000', NULL, 1),
(4195276, 603110, 81382, '<td valign="top">Lighting is a shame, the brightness makes the rest of it look dull. Blue colour cast too</td>', 'Lighting is a shame, the brightness makes the rest of it look dull. Blue colour cast too', '2007-10-25 15:06:48.000000', NULL, 1),
(4195279, 602267, 81382, '<td valign="top">Excellent B&amp;W tones. Composition and perspective are good too</td>', 'Excellent B&W tones. Composition and perspective are good too', '2007-10-25 15:07:33.000000', NULL, 1),
(4195281, 603306, 81382, '<td valign="top">Nicelly composed and good perspective distortion. A shame the chandelier doesn''t fit your title and the rest of the image but that can''t be helped</td>', 'Nicelly composed and good perspective distortion. A shame the chandelier doesn''t fit your title and the rest of the image but that can''t be helped', '2007-10-25 15:09:19.000000', NULL, 1),
