(4195286, 603226, 81382, '<td valign="top">Different...</td>', 'Different...', '2007-10-25 15:11:10.000000', NULL, 1),
(4195289, 603876, 81382, '<td valign="top">Shame about the fringing against the burnt out sky. More sharpening and contrast in the rock face would have made it more dramatic. A high contrast B&amp;W conversion would have been interesting to see</td>', 'Shame about the fringing against the burnt out sky. More sharpening and contrast in the rock face would have made it more dramatic. A high contrast B&W conversion would have been interesting to see', '2007-10-25 15:12:26.000000', NULL, 1),
