(4195324, 603890, 81382, '<td valign="top">Excellent capture. Background just a bit noisy/grainy and would have been spot on otherwise</td>', 'Excellent capture. Background just a bit noisy/grainy and would have been spot on otherwise', '2007-10-25 15:24:20.000000', NULL, 1),
(4195326, 603368, 32346, '<td valign="top">LOL</td>', 'LOL', '2007-10-25 15:24:49.000000', NULL, 1),
