(4195567, 602294, 58691, '<td valign="top">I like this shot and it''s starkness. Nicely done. The blue sky is a bit overpowering and this might have done better at greyscale.</td>', 'I like this shot and it''s starkness. Nicely done. The blue sky is a bit overpowering and this might have done better at greyscale.', '2007-10-25 17:20:48.000000', NULL, 1),
(4195572, 603920, 60987, '<td valign="top">nice composition but the image looks a little ''flat'', i''m guessing that may have been caused by hightlight reduction maybe?</td>', 'nice composition but the image looks a little ''flat'', i''m guessing that may have been caused by hightlight reduction maybe?', '2007-10-25 17:22:08.000000', NULL, 1),
(4195573, 603007, 58691, '<td valign="top">And hairy! Nice shot. I love how the perspective greatly distorts the horse''s body.</td>', 'And hairy! Nice shot. I love how the perspective greatly distorts the horse''s body.', '2007-10-25 17:22:32.000000', NULL, 1),
