(4207697, 602439, 27482, '<td valign="top">These shots are always cool and this one is very well done, congrats on the ribbon!</td>', 'These shots are always cool and this one is very well done, congrats on the ribbon!', '2007-10-31 06:57:59.000000', NULL, 0),
(4207700, 603890, 27482, '<td valign="top">I am a bit torn with the results of this challenge, I think the blue ribbon winner is more aesthetically pleasing, better composed and all that but the timing and moment you caught here is incredible so I am not really sure wich I want to like better, this is very cool and talk about correct shutterspeed and focus, dude, you really nailed that.  Congrats on your first ribbon!</td>', 'I am a bit torn with the results of this challenge, I think the blue ribbon winner is more aesthetically pleasing, better composed and all that but the timing and moment you caught here is incredible so I am not really sure wich I want to like better, this is very cool and talk about correct shutterspeed and focus, dude, you really nailed that.  Congrats on your first ribbon!', '2007-10-31 06:59:59.000000', NULL, 0),
(4207704, 603857, 73250, '<td valign="top">I actually would have liked to see you shooting this one! Great score. T.</td>', 'I actually would have liked to see you shooting this one! Great score. T.', '2007-10-31 07:04:05.000000', NULL, 0),
